def transform(grid):
    out=[row[:] for row in grid]
    bg=min(set(v for row in grid for v in row))
    # Background is the dominant color in these canvases.
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r,row in enumerate(grid):
        # Ignore wholly-background separator rows; extend the shape's rightward tail.
        nz=[c for c,v in enumerate(row) if v!=bg]
        if nz:
            end=max(nz)
            for c in range(end+1,len(row)):
                out[r][c]=1
    return out
